  test('GuessUp generation avoids serial AI roundtrips and all model prompts exclude player-identifying context', () => {
    const shell = read('frontend/src/AppShell.tsx')
    const rules = read('frontend/src/domain/games/guessup.ts')
    const adapter = read('backend/providers/generate.ts')
    const providerTests = read('backend/tests/providers.test.ts')
    const schema = read('backend/content/schema.ts')
    const schemaTests = read('backend/tests/schema.test.ts')
    const guessUpBranch = shell.slice(shell.indexOf("} else if (game === 'guessup')"), shell.indexOf("} else if (game === 'truth-or-dare')"))
    expect(guessUpBranch).toContain('count: 5')
    expect(guessUpBranch).not.toContain('count: 12')
    expect(guessUpBranch).not.toContain('playerNames:')
    expect(shell).not.toContain('playerNames:')
    expect(shell).not.toContain('playerCount:')
    expect(guessUpBranch).toContain('resolveGuessUpTeamBDeck')
    expect(rules).toContain('teamADeckFromGeneration')
    expect(providerTests).toContain('Generation prompts never include player names')
    expect(read('frontend/src/services/ai-providers.ts')).not.toContain('currentTurnPlayerNames')
    expect(read('frontend/src/services/ai-providers.ts')).not.toContain('playerNames: input.playerNames')
    expect(adapter).not.toContain('const allPlayerNames')
    expect(adapter).not.toContain('playerContext')
    expect(schema).toContain('delete safeInput.playerNames')
    expect(schema).toContain('delete safeInput.currentTurnPlayerNames')
    expect(schemaTests).toContain('strips it before provider routing')
  })

