  test('security headers use a strict same-origin script policy', () => {
    const vercel = json('vercel.json')
    const headers = vercel.headers.find((group: { source: string }) => group.source === '/(.*)').headers as { key: string; value: string }[]
    const values = new Map(headers.map(header => [header.key.toLowerCase(), header.value]))
    const csp = values.get('content-security-policy') ?? ''
    expect(csp).toContain("script-src 'self'")
    expect(csp).not.toContain('unsafe-eval')
    expect(csp).not.toContain("script-src 'self' 'unsafe-inline'")
    expect(csp).toContain("connect-src 'self'")
    expect(csp).toContain("object-src 'none'")
    expect(csp).toContain("frame-ancestors 'none'")
    expect(values.get('x-content-type-options')).toBe('nosniff')
    expect(values.get('x-frame-options')).toBe('DENY')
    expect(values.get('cross-origin-opener-policy')).toBe('same-origin')
    expect(values.get('cross-origin-resource-policy')).toBe('same-origin')
    const permissions = values.get('permissions-policy') ?? ''
    expect(permissions).toContain('microphone=(self)')
    expect(permissions).toContain('camera=()')
    expect(permissions).toContain('geolocation=()')
  })

  test('service worker and hashed assets have different cache lifetimes', () => {
    const vercel = json('vercel.json')
    const sw = vercel.headers.find((group: { source: string }) => group.source === '/sw.js')
    const assets = vercel.headers.find((group: { source: string }) => group.source === '/assets/(.*)')
    expect(sw?.headers.find((header: { key: string }) => header.key === 'Cache-Control')?.value).toContain('no-store')
    expect(assets?.headers.find((header: { key: string }) => header.key === 'Cache-Control')?.value).toContain('immutable')
  })

